        assertEquals("wrap position", 7, hf.findWrapPos(text, 8, 0));

        // starting from 8 must give -1 - the wrap pos is after end
        assertEquals("wrap position 2", -1, hf.findWrapPos(text, 8, 8));

        // words longer than the width are cut
        text = "aaaa aa";
